-- 01_schema_and_data.sql : creates tables and loads sample data (ANSI-friendly; runs on SQLite/MySQL/PostgreSQL)
DROP TABLE IF EXISTS order_items; DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS products;    DROP TABLE IF EXISTS customers;

CREATE TABLE customers (customer_id INT PRIMARY KEY, name VARCHAR(80) NOT NULL, email VARCHAR(100), city VARCHAR(50), signup_date DATE);
CREATE TABLE products  (product_id INT PRIMARY KEY, product_name VARCHAR(80) NOT NULL, category VARCHAR(50), price DECIMAL(10,2), stock_qty INT);
CREATE TABLE orders    (order_id INT PRIMARY KEY, customer_id INT REFERENCES customers(customer_id), order_date DATE, status VARCHAR(20));
CREATE TABLE order_items (item_id INT PRIMARY KEY, order_id INT REFERENCES orders(order_id), product_id INT REFERENCES products(product_id), quantity INT, unit_price DECIMAL(10,2));

